def solve(matrix):
    """Return the determinant of a square integer matrix exactly, using the
    fraction-free Bareiss algorithm. An empty matrix has determinant 1."""
    n = len(matrix)
    if n == 0:
        return 1
    # Work on an integer copy.
    a = [list(row) for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        # Find a nonzero pivot in column k at or below row k.
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]

