def solve(weights, values, capacity):
    """Return maximum total value of items with total weight <= capacity.
    Implements 0/1 knapsack DP with O(n*capacity) time.
    Handles zero‑weight items by adding their positive values directly, because they
    can be taken without affecting the capacity. Negative‑value zero‑weight items are
    ignored as they would only decrease the total.
    """
    if capacity < 0:
        return 0
    # Sum of values of zero‑weight items with positive value
    zero_sum = 0
    # Filter items: keep only those with positive weight <= capacity
    filtered = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_sum += v
        elif 0 < w <= capacity:
            filtered.append((w, v))
    # DP array where dp[c] is max value for exact weight c (excluding zero‑weight items)
    dp = [0] * (capacity + 1)
    for w, v in filtered:
        for c in range(capacity, w - 1, -1):
            cand = dp[c - w] + v
            if cand > dp[c]:
                dp[c] = cand
    # The best achievable value is the maximum over all feasible weights
    best = max(dp) if dp else 0
    return best + zero_sum

