def solve(path):
    """Simplify an absolute Unix path: resolve '.' and '..', collapse
    repeated slashes, drop trailing slashes; root stays '/'. Defensive
    against None/empty inputs."""
    if path is None:
        return '/'
    if not isinstance(path, str):
        path = str(path)
    if path == '':
        return '/'
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)

def solve(matrix):
    """Return the determinant of a square matrix exactly (fraction-free
    Bareiss arithmetic). Empty/degenerate matrices have determinant 1."""
    if matrix is None:
        return 1
    if not matrix:
        return 1
    rows = [list(r) for r in matrix]
    n = len(rows)
    if all(len(r) == 0 for r in rows):
        return 1  # degenerate case, e.g. [[]]
    from fractions import Fraction
    a = [[Fraction(x) for x in r] for r in rows]
    sign = 1
    prev = Fraction(1)
    for k in range(n - 1):
        if a[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) / prev
            a[i][k] = Fraction(0)
        prev = pivot
    det = sign * a[n - 1][n - 1]
    return int(det) if det.denominator == 1 else det

