def solve(a, b):
    """Return Levenshtein distance between strings a and b."""
    if not isinstance(a, str):
        a = str(a)
    if not isinstance(b, str):
        b = str(b)
    n, m = len(a), len(b)
    if n == 0:
        return m
    if m == 0:
        return n
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            cost = 0 if ai == b[j - 1] else 1
            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
        prev = cur
    return prev[m]

def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount*.
    *coins* is a list of non‑negative integers (coin denominations). Unlimited
    supply of each coin is available. Return -1 if the amount cannot be formed.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non‑positive coins (zero or negative) to avoid infinite loops
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # Use a DP array of size amount+1
    INF = amount + 1  # any value larger than possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

