def solve(weights, values, capacity):
    """0/1 knapsack: largest total value of items (each used at most once)
    whose weights fit within capacity. Bottom-up DP over capacities."""
    if capacity is None:
        return 0
    if capacity <= 0:
        return 0
    cap = int(capacity)
    dp = [0] * (cap + 1)
    for w, v in zip(weights, values):
        if w is None or w <= 0:
            # Zero/unknown weight: taking it never exceeds capacity.
            if w == 0 and v:
                for c in range(cap, -1, -1):
                    dp[c] = max(dp[c], dp[c] + v)
            continue
        for c in range(cap, w - 1, -1):
            cand = dp[c - w] + v
            if cand > dp[c]:
                dp[c] = cand
    return dp[cap]

