def solve(grid):
    """Count the number of islands in a 2D grid.
    The grid is a list of lists containing 0s and 1s (any other values are
    treated as water). Islands are formed by horizontally or vertically
    adjacent cells with value 1. Empty or malformed inputs yield 0.
    """
    # Guard against non‑list inputs
    if not isinstance(grid, list) or not grid:
        return 0
    rows = len(grid)
    cols = max((len(r) for r in grid if isinstance(r, list)), default=0)
    if cols == 0:
        return 0

    visited = [[False] * cols for _ in range(rows)]
    def is_land(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        try:
            val = grid[r][c]
        except Exception:
            return False
        return val == 1

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if cr < 0 or cr >= rows or cc < 0 or cc >= cols:
                continue
            if visited[cr][cc]:
                continue
            try:
                if grid[cr][cc] != 1:
                    continue
            except Exception:
                continue
            visited[cr][cc] = True
            # four directions
            stack.append((cr - 1, cc))
            stack.append((cr + 1, cc))
            stack.append((cr, cc - 1))
            stack.append((cr, cc + 1))

    count = 0
    for r in range(rows):
        for c in range(cols):
            if visited[r][c]:
                continue
            if is_land(r, c):
                count += 1
                dfs(r, c)
    return count

