def solve(tokens):
    ops = {'+', '-', '*', '/'}
    stack = []
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:
                q = int(a / b)
                stack.append(q)
        else:
            stack.append(int(tok))
    return stack[0] if len(stack) == 1 else stack[-1]

