def solve(coins, amount):
    """Fewest coins (unlimited supply of each value) summing to amount;
    -1 if impossible. Bottom-up unbounded knapsack-style DP."""
    if amount == 0:
        return 0
    if amount is None or amount < 0:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
    for c in range(1, amount + 1):
        best = INF
        for v in coins:
            if v and v > 0 and v <= c and dp[c - v] + 1 < best:
                best = dp[c - v] + 1
        dp[c] = best
    return dp[amount] if dp[amount] != INF else -1

