def solve(*args, **kwargs):
    """Validate IPv4 address.
    Handles missing or extra arguments gracefully by returning ``False`` when the
    primary argument is not provided or not a proper string.
    """
    if not args:
        return False
    s = args[0]
    # Accept bytes by decoding; everything else must be a string.
    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception:
            return False
    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if not (0 <= val <= 255):
            return False
    return True
